  1→// Package settings provides configuration loading for Entire.
  2→// This package is separate from cli to allow strategy package to import it
  3→// without creating an import cycle (cli imports strategy).
  4→package settings
  5→
  6→import (
  7→	"bytes"
  8→	"context"
  9→	"encoding/json"
 10→	"fmt"
 11→	"os"
 12→	"path/filepath"
 13→
 14→	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
 15→	"github.com/entireio/cli/cmd/entire/cli/paths"
 16→)
 17→
 18→const (
 19→	// EntireSettingsFile is the path to the Entire settings file
 20→	EntireSettingsFile = ".entire/settings.json"
 21→	// EntireSettingsLocalFile is the path to the local settings override file (not committed)
 22→	EntireSettingsLocalFile = ".entire/settings.local.json"
 23→)
 24→
 25→// Commit linking mode constants.
 26→const (
 27→	// CommitLinkingAlways auto-links commits to sessions without prompting.
 28→	CommitLinkingAlways = "always"
 29→	// CommitLinkingPrompt prompts the user on each commit (default for existing users).
 30→	CommitLinkingPrompt = "prompt"
 31→)
 32→
 33→// EntireSettings represents the .entire/settings.json configuration
 34→type EntireSettings struct {
 35→
 36→	// Enabled indicates whether Entire is active. When false, CLI commands
 37→	// show a disabled message and hooks exit silently. Defaults to true.
 38→	Enabled bool `json:"enabled"`
 39→
 40→	// LocalDev indicates whether to use "go run" instead of the "entire" binary
 41→	// This is used for development when the binary is not installed
 42→	LocalDev bool `json:"local_dev,omitempty"`
 43→
 44→	// LogLevel sets the logging verbosity (debug, info, warn, error).
 45→	// Can be overridden by ENTIRE_LOG_LEVEL environment variable.
 46→	// Defaults to "info".
 47→	LogLevel string `json:"log_level,omitempty"`
 48→
 49→	// StrategyOptions contains strategy-specific configuration
 50→	StrategyOptions map[string]any `json:"strategy_options,omitempty"`
 51→
 52→	// AbsoluteGitHookPath embeds the full binary path in git hooks instead of
 53→	// bare "entire". This is needed for GUI git clients (Xcode, Tower, etc.)
 54→	// that don't source shell profiles and can't find "entire" on PATH.
 55→	AbsoluteGitHookPath bool `json:"absolute_git_hook_path,omitempty"`
 56→
 57→	// Telemetry controls anonymous usage analytics.
 58→	// nil = not asked yet (show prompt), true = opted in, false = opted out
 59→	Telemetry *bool `json:"telemetry,omitempty"`
 60→
 61→	// CommitLinking controls how commits are linked to agent sessions.
 62→	// "always" = auto-link without prompting, "prompt" = ask on each commit.
 63→	// Defaults to "prompt" (preserves existing user behavior).
 64→	CommitLinking string `json:"commit_linking,omitempty"`
 65→
 66→	// ExternalAgents enables discovery and registration of external agent
 67→	// plugins (entire-agent-* binaries on $PATH). Defaults to false.
 68→	ExternalAgents bool `json:"external_agents,omitempty"`
 69→
 70→	// Deprecated: no longer used. Exists to tolerate old settings files
 71→	// that still contain "strategy": "auto-commit" or similar.
 72→	Strategy string `json:"strategy,omitempty"`
 73→}
 74→
 75→// GetCommitLinking returns the effective commit linking mode.
 76→// Returns the explicit value if set, otherwise defaults to "prompt"
 77→// to preserve existing user behavior.
 78→func (s *EntireSettings) GetCommitLinking() string {
 79→	if s.CommitLinking != "" {
 80→		return s.CommitLinking
 81→	}
 82→	return CommitLinkingPrompt
 83→}
