291→// IsSummarizeEnabled checks if auto-summarize is enabled in settings.
292→// Returns false by default if settings cannot be loaded or the key is missing.
293→func IsSummarizeEnabled(ctx context.Context) bool {
294→	settings, err := Load(ctx)
295→	if err != nil {
296→		return false
297→	}
298→	return settings.IsSummarizeEnabled()
299→}
