317→// GetCheckpointRemote returns the configured checkpoint remote URL.
318→// This is a full git remote URL (SSH or HTTPS) used for pushing/fetching
319→// the entire/checkpoints/v1 and entire/trails/v1 branches to a separate remote.
320→// Returns empty string if not configured or invalid type.
321→func (s *EntireSettings) GetCheckpointRemote() string {
322→	if s.StrategyOptions == nil {
323→		return ""
324→	}
325→	val, ok := s.StrategyOptions["checkpoint_remote"]
326→	if !ok {
327→		return ""
328→	}
329→	str, ok := val.(string)
330→	if !ok || str == "" {
331→		return ""
332→	}
333→	return str
334→}
