336→// IsPushSessionsDisabled checks if push_sessions is disabled in settings.
337→// Returns true if push_sessions is explicitly set to false.
338→func (s *EntireSettings) IsPushSessionsDisabled() bool {
339→	if s.StrategyOptions == nil {
340→		return false
341→	}
342→	val, exists := s.StrategyOptions["push_sessions"]
343→	if !exists {
344→		return false
345→	}
346→	if boolVal, ok := val.(bool); ok {
347→		return !boolVal // disabled = !push_sessions
348→	}
349→	return false
350→}
