372→// saveToFile saves settings to the specified file path.
373→func saveToFile(ctx context.Context, settings *EntireSettings, filePath string) error {
374→	// Get absolute path for the file
375→	filePathAbs, err := paths.AbsPath(ctx, filePath)
376→	if err != nil {
377→		filePathAbs = filePath // Fallback to relative
378→	}
379→
380→	// Ensure directory exists
381→	dir := filepath.Dir(filePathAbs)
382→	if err := os.MkdirAll(dir, 0o750); err != nil {
383→		return fmt.Errorf("creating settings directory: %w", err)
384→	}
385→
386→	data, err := jsonutil.MarshalIndentWithNewline(settings, "", "  ")
387→	if err != nil {
388→		return fmt.Errorf("marshaling settings: %w", err)
389→	}
390→
391→	//nolint:gosec // G306: settings file is config, not secrets; 0o644 is appropriate
392→	if err := os.WriteFile(filePathAbs, data, 0o644); err != nil {
393→		return fmt.Errorf("writing settings file: %w", err)
394→	}
395→	return nil
396→}
