 187→// runEnableInteractive runs the interactive enable flow.
 188→// agents must be provided by the caller (via detectOrSelectAgent).
 189→func runEnableInteractive(ctx context.Context, w io.Writer, agents []agent.Agent, opts EnableOptions) error {
 190→	// Uninstall hooks for agents that were previously active but are no longer selected
 191→	if err := uninstallDeselectedAgentHooks(ctx, w, agents); err != nil {
 192→		return fmt.Errorf("failed to clean up deselected agents: %w", err)
 193→	}
 194→
 195→	// Setup agent hooks for all selected agents
 196→	for _, ag := range agents {
 197→		if _, err := setupAgentHooks(ctx, ag, opts.LocalDev, opts.ForceHooks); err != nil {
 198→			return fmt.Errorf("failed to setup %s hooks: %w", ag.Type(), err)
 199→		}
 200→	}
 201→
 202→	// Setup .entire directory
 203→	if _, err := setupEntireDirectory(ctx); err != nil {
 204→		return fmt.Errorf("failed to setup .entire directory: %w", err)
 205→	}
 206→
 207→	// Load existing settings to preserve other options (like strategy_options.push)
 208→	settings, err := LoadEntireSettings(ctx)
 209→	if err != nil {
 210→		// If we can't load, start with defaults
 211→		settings = &EntireSettings{}
 212→	}
 213→	// Update the specific fields
 214→	settings.Enabled = true
 215→	if opts.LocalDev {
 216→		settings.LocalDev = true
 217→	}
 218→	if opts.AbsoluteGitHookPath {
 219→		settings.AbsoluteGitHookPath = true
 220→	}
 221→
 222→	opts.applyStrategyOptions(settings)
 223→
 224→	// Determine which settings file to write to
 225→	// First run always creates settings.json (no prompt)
 226→	entireDirAbs, err := paths.AbsPath(ctx, paths.EntireDir)
 227→	if err != nil {
 228→		entireDirAbs = paths.EntireDir // Fallback to relative
 229→	}
 230→	shouldUseLocal, showNotification := determineSettingsTarget(entireDirAbs, opts.UseLocalSettings, opts.UseProjectSettings)
 231→
 232→	if showNotification {
 233→		fmt.Fprintln(w, "Info: Project settings exist. Saving to settings.local.json instead.")
 234→		fmt.Fprintln(w, "  Use --project to update the project settings file.")
 235→	}
 236→
 237→	// Save settings to the appropriate file.
 238→	saveSettings := func() error {
 239→		if shouldUseLocal {
 240→			return SaveEntireSettingsLocal(ctx, settings)
 241→		}
 242→		return SaveEntireSettings(ctx, settings)
 243→	}
 244→	if err := saveSettings(); err != nil {
 245→		return fmt.Errorf("failed to save settings: %w", err)
 246→	}
 247→
 248→	// Use settings values (merged from existing config + flags) for hook installation
 249→	// This ensures re-running `entire enable` without flags preserves existing settings
 250→	if _, err := strategy.InstallGitHook(ctx, true, settings.LocalDev, settings.AbsoluteGitHookPath); err != nil {
 251→		return fmt.Errorf("failed to install git hooks: %w", err)
 252→	}
 253→	strategy.CheckAndWarnHookManagers(ctx, w, settings.LocalDev, settings.AbsoluteGitHookPath)
 254→	fmt.Fprintln(w, "✓ Hooks installed")
 255→
 256→	configDisplay := configDisplayProject
 257→	if shouldUseLocal {
 258→		configDisplay = configDisplayLocal
 259→	}
 260→	fmt.Fprintf(w, "✓ Project configured (%s)\n", configDisplay)
 261→
 262→	// Ask about telemetry consent (only if not already asked)
 263→	fmt.Fprintln(w)
 264→	if err := promptTelemetryConsent(settings, opts.Telemetry); err != nil {
 265→		return fmt.Errorf("telemetry consent: %w", err)
 266→	}
 267→	// Save again to persist telemetry choice
 268→	if err := saveSettings(); err != nil {
 269→		return fmt.Errorf("failed to save settings: %w", err)
 270→	}
 271→
 272→	if err := strategy.EnsureSetup(ctx); err != nil {
 273→		return fmt.Errorf("failed to setup strategy: %w", err)
 274→	}
 275→
 276→	fmt.Fprintln(w, "\nReady.")
 277→
 278→	return nil
 279→}
