 324→// checkDisabledGuard checks if Entire is disabled and prints a message if so.
 325→// Returns true if the caller should exit (i.e., Entire is disabled).
 326→// On error reading settings, defaults to enabled (returns false).
 327→func checkDisabledGuard(ctx context.Context, w io.Writer) bool {
 328→	enabled, err := IsEnabled(ctx)
