 340→// uninstallDeselectedAgentHooks removes hooks for agents that were previously
 341→// installed but are not in the selected list. This handles the case where a user
 342→// re-runs `entire enable` and deselects an agent.
 343→func uninstallDeselectedAgentHooks(ctx context.Context, w io.Writer, selectedAgents []agent.Agent) error {
 344→	installedNames := GetAgentsWithHooksInstalled(ctx)
 345→	if len(installedNames) == 0 {
 346→		return nil
 347→	}
 348→
 349→	selectedSet := make(map[types.AgentName]struct{}, len(selectedAgents))
 350→	for _, ag := range selectedAgents {
 351→		selectedSet[ag.Name()] = struct{}{}
 352→	}
 353→
 354→	var errs []error
 355→	for _, name := range installedNames {
 356→		if _, selected := selectedSet[name]; selected {
 357→			continue
 358→		}
 359→		ag, err := agent.Get(name)
 360→		if err != nil {
 361→			continue
 362→		}
 363→		hookAgent, ok := agent.AsHookSupport(ag)
 364→		if !ok {
 365→			continue
 366→		}
 367→		if err := hookAgent.UninstallHooks(ctx); err != nil {
 368→			errs = append(errs, fmt.Errorf("failed to uninstall %s hooks: %w", ag.Type(), err))
 369→		} else {
 370→			fmt.Fprintf(w, "Removed %s hooks\n", ag.Type())
 371→		}
 372→	}
 373→	return errors.Join(errs...)
 374→}
