 376→// setupAgentHooks sets up hooks for a given agent.
 377→// Returns the number of hooks installed (0 if already installed).
 378→func setupAgentHooks(ctx context.Context, ag agent.Agent, localDev, forceHooks bool) (int, error) {
 379→	hookAgent, ok := agent.AsHookSupport(ag)
 380→	if !ok {
 381→		return 0, fmt.Errorf("agent %s does not support hooks", ag.Name())
 382→	}
 383→
 384→	count, err := hookAgent.InstallHooks(ctx, localDev, forceHooks)
 385→	if err != nil {
 386→		return 0, fmt.Errorf("failed to install %s hooks: %w", ag.Name(), err)
 387→	}
 388→
 389→	return count, nil
 390→}
