 392→// detectOrSelectAgent tries to auto-detect agents, or prompts the user to select.
 393→// Returns the detected/selected agents and any error.
 394→//
 395→// On first run (no hooks installed):
 396→//   - Single detected agent: used automatically
 397→//   - Multiple/no detected agents: interactive multi-select prompt
 398→//
 399→// On re-run (hooks already installed):
 400→//   - Always shows the interactive multi-select
 401→//   - Pre-selects only agents that have hooks installed (respects prior deselection)
 402→//
 403→// selectFn overrides the interactive prompt for testing. When nil, the real form is used.
 404→// It receives available agent names and returns the selected names.
 405→func detectOrSelectAgent(ctx context.Context, w io.Writer, selectFn func(available []string) ([]string, error)) ([]agent.Agent, error) {
 406→	// Check for agents with hooks already installed (re-run detection)
 407→	installedAgentNames := GetAgentsWithHooksInstalled(ctx)
 408→	hasInstalledHooks := len(installedAgentNames) > 0
 409→
 410→	// Try auto-detection
 411→	detected := agent.DetectAll(ctx)
 412→
 413→	// First run: use existing auto-detect shortcuts
 414→	if !hasInstalledHooks {
 415→		switch {
 416→		case len(detected) == 1:
 417→			fmt.Fprintf(w, "Detected agent: %s\n\n", detected[0].Type())
 418→			return detected, nil
 419→
 420→		case len(detected) > 1:
 421→			agentTypes := make([]string, 0, len(detected))
 422→			for _, ag := range detected {
 423→				agentTypes = append(agentTypes, string(ag.Type()))
 424→			}
 425→			fmt.Fprintf(w, "Detected multiple agents: %s\n", strings.Join(agentTypes, ", "))
 426→			fmt.Fprintln(w)
 427→		}
 428→	}
 429→
 430→	// Check if we can prompt interactively
 431→	if !canPromptInteractively() {
 432→		if hasInstalledHooks {
 433→			// Re-run without TTY — keep currently installed agents
 434→			agents := make([]agent.Agent, 0, len(installedAgentNames))
 435→			for _, name := range installedAgentNames {
 436→				ag, err := agent.Get(name)
 437→				if err != nil {
 438→					continue
 439→				}
 440→				agents = append(agents, ag)
 441→			}
 442→			return agents, nil
 443→		}
 444→		if len(detected) > 0 {
 445→			return detected, nil
 446→		}
 447→		defaultAgent := agent.Default()
 448→		if defaultAgent == nil {
 449→			return nil, errors.New("no default agent available")
 450→		}
 451→		fmt.Fprintf(w, "Agent: %s (use --agent to change)\n\n", defaultAgent.Type())
 452→		return []agent.Agent{defaultAgent}, nil
 453→	}
 454→
 455→	if !hasInstalledHooks && len(detected) == 0 {
 456→		fmt.Fprintln(w, "No agent configuration detected (e.g., "+strings.Join(agent.StringList(), ", ")+").")
 457→		fmt.Fprintln(w, "This is normal - some agents don't require a config directory.")
 458→		fmt.Fprintln(w)
 459→	}
 460→
 461→	// Build pre-selection set.
 462→	// On re-run: only pre-select agents with hooks installed (respect prior deselection).
 463→	// On first run: pre-select all detected agents.
 464→	preSelectedSet := make(map[types.AgentName]struct{})
 465→	if hasInstalledHooks {
 466→		for _, name := range installedAgentNames {
 467→			preSelectedSet[name] = struct{}{}
 468→		}
 469→	} else {
 470→		for _, ag := range detected {
 471→			preSelectedSet[ag.Name()] = struct{}{}
 472→		}
 473→	}
 474→
 475→	// Build options from registered agents
 476→	agentNames := agent.List()
 477→	options := make([]huh.Option[string], 0, len(agentNames))
 478→	for _, name := range agentNames {
 479→		ag, err := agent.Get(name)
 480→		if err != nil {
 481→			continue
 482→		}
 483→		// Only show agents that support hooks
 484→		if _, ok := agent.AsHookSupport(ag); !ok {
 485→			continue
 486→		}
 487→		// Skip test-only agents (e.g., Vogon canary)
 488→		if to, ok := ag.(agent.TestOnly); ok && to.IsTestOnly() {
 489→			continue
 490→		}
 491→		opt := huh.NewOption(string(ag.Type()), string(name))
 492→		if _, isPreSelected := preSelectedSet[name]; isPreSelected {
 493→			opt = opt.Selected(true)
 494→		}
 495→		options = append(options, opt)
 496→	}
 497→
 498→	if len(options) == 0 {
 499→		return nil, errors.New("no agents with hook support available")
 500→	}
 501→
 502→	// Collect available agent names for the selector
 503→	availableNames := make([]string, 0, len(options))
 504→	for _, opt := range options {
 505→		availableNames = append(availableNames, opt.Value)
 506→	}
 507→
 508→	var selectedAgentNames []string
 509→	if selectFn != nil {
 510→		var err error
 511→		selectedAgentNames, err = selectFn(availableNames)
 512→		if err != nil {
 513→			return nil, err
 514→		}
 515→		if len(selectedAgentNames) == 0 {
 516→			return nil, errors.New("no agents selected")
 517→		}
 518→	} else {
 519→		form := NewAccessibleForm(
 520→			huh.NewGroup(
 521→				huh.NewMultiSelect[string]().
 522→					Title("Which agents are you using?").
 523→					Description("Use space to select, enter to confirm.").
 524→					Options(options...).
 525→					Validate(func(selected []string) error {
 526→						if len(selected) == 0 {
 527→							return errors.New("please select at least one agent")
 528→						}
 529→						return nil
 530→					}).
 531→					Value(&selectedAgentNames),
 532→			),
 533→		)
 534→		if err := form.Run(); err != nil {
 535→			return nil, fmt.Errorf("agent selection cancelled: %w", err)
 536→		}
 537→	}
 538→
 539→	selectedAgents := make([]agent.Agent, 0, len(selectedAgentNames))
 540→	for _, name := range selectedAgentNames {
 541→		selectedAgent, err := agent.Get(types.AgentName(name))
 542→		if err != nil {
 543→			return nil, fmt.Errorf("failed to get selected agent %s: %w", name, err)
 544→		}
 545→		selectedAgents = append(selectedAgents, selectedAgent)
 546→	}
 547→
 548→	agentTypes := make([]string, 0, len(selectedAgents))
