 599→// setupAgentHooksNonInteractive sets up hooks for a specific agent non-interactively.
 600→// If strategyName is provided, it sets the strategy; otherwise uses default.
 601→func setupAgentHooksNonInteractive(ctx context.Context, w io.Writer, ag agent.Agent, opts EnableOptions) error {
 602→	agentName := ag.Name()
 603→	// Check if agent supports hooks
 604→	hookAgent, ok := agent.AsHookSupport(ag)
 605→	if !ok {
 606→		return fmt.Errorf("agent %s does not support hooks", agentName)
 607→	}
 608→
 609→	fmt.Fprintf(w, "Agent: %s\n\n", ag.Type())
 610→
 611→	// Install agent hooks (agent hooks don't depend on settings)
 612→	installedHooks, err := hookAgent.InstallHooks(ctx, opts.LocalDev, opts.ForceHooks)
 613→	if err != nil {
 614→		return fmt.Errorf("failed to install hooks for %s: %w", agentName, err)
 615→	}
 616→
 617→	// Setup .entire directory
 618→	if _, err := setupEntireDirectory(ctx); err != nil {
 619→		return fmt.Errorf("failed to setup .entire directory: %w", err)
 620→	}
 621→
 622→	// Load existing settings to preserve other options (like strategy_options.push)
 623→	settings, err := LoadEntireSettings(ctx)
 624→	if err != nil {
 625→		// If we can't load, start with defaults
 626→		settings = &EntireSettings{}
 627→	}
 628→	settings.Enabled = true
 629→	if opts.LocalDev {
 630→		settings.LocalDev = true
 631→	}
 632→	if opts.AbsoluteGitHookPath {
 633→		settings.AbsoluteGitHookPath = true
 634→	}
 635→
 636→	opts.applyStrategyOptions(settings)
 637→
 638→	// Handle telemetry for non-interactive mode
 639→	// Note: if telemetry is nil (not configured), it defaults to disabled
 640→	if !opts.Telemetry || os.Getenv("ENTIRE_TELEMETRY_OPTOUT") != "" {
 641→		f := false
 642→		settings.Telemetry = &f
 643→	}
 644→
 645→	if err := SaveEntireSettings(ctx, settings); err != nil {
 646→		return fmt.Errorf("failed to save settings: %w", err)
 647→	}
 648→
 649→	// Use settings values (merged from existing config + flags) for hook installation
 650→	// This ensures re-running `entire enable --agent X` without flags preserves existing settings
 651→	if _, err := strategy.InstallGitHook(ctx, true, settings.LocalDev, settings.AbsoluteGitHookPath); err != nil {
 652→		return fmt.Errorf("failed to install git hooks: %w", err)
 653→	}
 654→	strategy.CheckAndWarnHookManagers(ctx, w, settings.LocalDev, settings.AbsoluteGitHookPath)
 655→
 656→	if installedHooks == 0 {
 657→		msg := fmt.Sprintf("Hooks for %s already installed", ag.Description())
 658→		if ag.IsPreview() {
 659→			msg += " (Preview)"
 660→		}
 661→		fmt.Fprintf(w, "%s\n", msg)
 662→	} else {
 663→		msg := fmt.Sprintf("Installed %d hooks for %s", installedHooks, ag.Description())
 664→		if ag.IsPreview() {
 665→			msg += " (Preview)"
 666→		}
 667→		fmt.Fprintf(w, "%s\n", msg)
 668→	}
 669→
 670→	fmt.Fprintf(w, "✓ Project configured (%s)\n", configDisplayProject)
 671→
 672→	if err := strategy.EnsureSetup(ctx); err != nil {
 673→		return fmt.Errorf("failed to setup strategy: %w", err)
 674→	}
 675→
 676→	fmt.Fprintln(w, "\nReady.")
 677→
 678→	return nil
 679→}
