 785→// shellCompletionComment is the comment preceding the completion line
 786→const shellCompletionComment = "# Entire CLI shell completion"
 787→
 788→// errUnsupportedShell is returned when the user's shell is not supported for completion.
 789→var errUnsupportedShell = errors.New("unsupported shell")
 790→
 791→// shellCompletionTarget returns the rc file path and completion lines for the
 792→// user's current shell.
 793→func shellCompletionTarget() (shellName, rcFile, completionLine string, err error) {
 794→	home, err := os.UserHomeDir()
 795→	if err != nil {
 796→		return "", "", "", fmt.Errorf("cannot determine home directory: %w", err)
 797→	}
 798→
 799→	shell := os.Getenv("SHELL")
 800→	switch {
 801→	case strings.Contains(shell, "zsh"):
 802→		return "Zsh",
 803→			filepath.Join(home, ".zshrc"),
 804→			"autoload -Uz compinit && compinit && source <(entire completion zsh)",
 805→			nil
 806→	case strings.Contains(shell, "bash"):
 807→		bashRC := filepath.Join(home, ".bashrc")
 808→		if _, err := os.Stat(filepath.Join(home, ".bash_profile")); err == nil {
 809→			bashRC = filepath.Join(home, ".bash_profile")
 810→		}
 811→		return "Bash",
 812→			bashRC,
 813→			"source <(entire completion bash)",
 814→			nil
 815→	case strings.Contains(shell, "fish"):
 816→		return "Fish",
 817→			filepath.Join(home, ".config", "fish", "config.fish"),
 818→			"entire completion fish | source",
 819→			nil
 820→	default:
 821→		return "", "", "", errUnsupportedShell
 822→	}
 823→}
 824→
 825→// promptShellCompletion offers to add shell completion to the user's rc file.
 826→// Only prompts if completion is not already configured.
 827→func promptShellCompletion(w io.Writer) error {
 828→	shellName, rcFile, completionLine, err := shellCompletionTarget()
 829→	if err != nil {
 830→		if errors.Is(err, errUnsupportedShell) {
 831→			fmt.Fprintf(w, "Note: Shell completion not available for your shell. Supported: zsh, bash, fish.\n")
 832→			return nil
 833→		}
 834→		return fmt.Errorf("shell completion: %w", err)
 835→	}
 836→
 837→	if isCompletionConfigured(rcFile) {
 838→		fmt.Fprintf(w, "✓ Shell completion already configured in %s\n", rcFile)
 839→		return nil
 840→	}
 841→
 842→	var selected string
 843→	form := NewAccessibleForm(
 844→		huh.NewGroup(
 845→			huh.NewSelect[string]().
 846→				Title(fmt.Sprintf("Enable shell completion? (detected: %s)", shellName)).
 847→				Options(
 848→					huh.NewOption("Yes", "yes"),
 849→					huh.NewOption("No", "no"),
 850→				).
 851→				Value(&selected),
 852→		),
 853→	)
 854→
 855→	if err := form.Run(); err != nil {
 856→		//nolint:nilerr // User cancelled - not a fatal error, just skip
 857→		return nil
 858→	}
 859→
 860→	if selected != "yes" {
 861→		return nil
 862→	}
 863→
 864→	if err := appendShellCompletion(rcFile, completionLine); err != nil {
 865→		return fmt.Errorf("failed to update %s: %w", rcFile, err)
 866→	}
 867→
 868→	fmt.Fprintf(w, "✓ Shell completion added to %s\n", rcFile)
 869→	fmt.Fprintln(w, "  Restart your shell to activate")
 870→
 871→	return nil
 872→}
 873→
 874→// isCompletionConfigured checks if shell completion is already in the rc file.
 875→func isCompletionConfigured(rcFile string) bool {
 876→	//nolint:gosec // G304: rcFile is constructed from home dir + known filename, not user input
 877→	content, err := os.ReadFile(rcFile)
 878→	if err != nil {
 879→		return false // File doesn't exist or can't read, treat as not configured
 880→	}
 881→	return strings.Contains(string(content), "entire completion")
 882→}
 883→
 884→// appendShellCompletion adds the completion line to the rc file.
 885→func appendShellCompletion(rcFile, completionLine string) error {
 886→	if err := os.MkdirAll(filepath.Dir(rcFile), 0o700); err != nil {
 887→		return fmt.Errorf("creating directory: %w", err)
 888→	}
 889→	//nolint:gosec // G302: Shell rc files need 0644 for user readability
 890→	f, err := os.OpenFile(rcFile, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o644)
 891→	if err != nil {
 892→		return fmt.Errorf("opening file: %w", err)
 893→	}
 894→	defer f.Close()
 895→
 896→	_, err = f.WriteString("\n" + shellCompletionComment + "\n" + completionLine + "\n")
 897→	if err != nil {
 898→		return fmt.Errorf("writing completion: %w", err)
 899→	}
 900→	return nil
 901→}
