 946→// runUninstall completely removes Entire from the repository.
 947→func runUninstall(ctx context.Context, w, errW io.Writer, force bool) error {
 948→	// Check if we're in a git repository
 949→	if _, err := paths.WorktreeRoot(ctx); err != nil {
 950→		fmt.Fprintln(errW, "Not a git repository. Nothing to uninstall.")
 951→		return NewSilentError(errors.New("not a git repository"))
 952→	}
 953→
 954→	// Gather counts for display
 955→	sessionStateCount := countSessionStates(ctx)
 956→	shadowBranchCount := countShadowBranches(ctx)
 957→	gitHooksInstalled := strategy.IsGitHookInstalled(ctx)
 958→	agentsWithInstalledHooks := GetAgentsWithHooksInstalled(ctx)
 959→	entireDirExists := checkEntireDirExists(ctx)
 960→
 961→	// Check if there's anything to uninstall
 962→	if !entireDirExists && !gitHooksInstalled && sessionStateCount == 0 &&
 963→		shadowBranchCount == 0 && len(agentsWithInstalledHooks) == 0 {
 964→		fmt.Fprintln(w, "Entire is not installed in this repository.")
 965→		return nil
 966→	}
 967→
 968→	// Show confirmation prompt unless --force
 969→	if !force {
 970→		fmt.Fprintln(w, "\nThis will completely remove Entire from this repository:")
 971→		if entireDirExists {
 972→			fmt.Fprintln(w, "  - .entire/ directory")
 973→		}
 974→		if gitHooksInstalled {
 975→			fmt.Fprintln(w, "  - Git hooks (prepare-commit-msg, commit-msg, post-commit, pre-push)")
 976→		}
 977→		if sessionStateCount > 0 {
 978→			fmt.Fprintf(w, "  - Session state files (%d)\n", sessionStateCount)
 979→		}
 980→		if shadowBranchCount > 0 {
 981→			fmt.Fprintf(w, "  - Shadow branches (%d)\n", shadowBranchCount)
 982→		}
 983→		if len(agentsWithInstalledHooks) > 0 {
 984→			displayNames := make([]string, 0, len(agentsWithInstalledHooks))
 985→			for _, name := range agentsWithInstalledHooks {
 986→				if ag, err := agent.Get(name); err == nil {
 987→					displayNames = append(displayNames, string(ag.Type()))
 988→				}
 989→			}
 990→			fmt.Fprintf(w, "  - Agent hooks (%s)\n", strings.Join(displayNames, ", "))
 991→		}
 992→		fmt.Fprintln(w)
 993→
 994→		var confirmed bool
 995→		form := NewAccessibleForm(
 996→			huh.NewGroup(
 997→				huh.NewConfirm().
 998→					Title("Are you sure you want to uninstall Entire?").
 999→					Affirmative("Yes, uninstall").
1000→					Negative("Cancel").
1001→					Value(&confirmed),
1002→			),
1003→		)
1004→
1005→		if err := form.Run(); err != nil {
1006→			return fmt.Errorf("confirmation cancelled: %w", err)
1007→		}
1008→
1009→		if !confirmed {
1010→			fmt.Fprintln(w, "Uninstall cancelled.")
1011→			return nil
1012→		}
1013→	}
1014→
1015→	fmt.Fprintln(w, "\nUninstalling Entire CLI...")
1016→
1017→	// 1. Remove agent hooks (lowest risk)
1018→	if err := removeAgentHooks(ctx, w); err != nil {
1019→		fmt.Fprintf(errW, "Warning: failed to remove agent hooks: %v\n", err)
1020→	}
1021→
1022→	// 2. Remove git hooks
1023→	removed, err := strategy.RemoveGitHook(ctx)
1024→	if err != nil {
1025→		fmt.Fprintf(errW, "Warning: failed to remove git hooks: %v\n", err)
1026→	} else if removed > 0 {
1027→		fmt.Fprintf(w, "  Removed git hooks (%d)\n", removed)
1028→	}
1029→
1030→	// 3. Remove session state files
1031→	statesRemoved, err := removeAllSessionStates(ctx)
1032→	if err != nil {
1033→		fmt.Fprintf(errW, "Warning: failed to remove session states: %v\n", err)
1034→	} else if statesRemoved > 0 {
1035→		fmt.Fprintf(w, "  Removed session states (%d)\n", statesRemoved)
1036→	}
1037→
1038→	// 4. Remove .entire/ directory
1039→	if err := removeEntireDirectory(ctx); err != nil {
1040→		fmt.Fprintf(errW, "Warning: failed to remove .entire directory: %v\n", err)
1041→	} else if entireDirExists {
1042→		fmt.Fprintln(w, "  Removed .entire directory")
1043→	}
1044→
1045→	// 5. Remove shadow branches
1046→	branchesRemoved, err := removeAllShadowBranches(ctx)
1047→	if err != nil {
1048→		fmt.Fprintf(errW, "Warning: failed to remove shadow branches: %v\n", err)
1049→	} else if branchesRemoved > 0 {
1050→		fmt.Fprintf(w, "  Removed %d shadow branches\n", branchesRemoved)
1051→	}
1052→
1053→	fmt.Fprintln(w, "\nEntire CLI uninstalled successfully.")
1054→	return nil
1055→}
