1089→// removeAgentHooks removes hooks from all agents that support hooks.
1090→func removeAgentHooks(ctx context.Context, w io.Writer) error {
1091→	var errs []error
1092→	for _, name := range agent.List() {
1093→		ag, err := agent.Get(name)
1094→		if err != nil {
1095→			continue
1096→		}
1097→		hs, ok := agent.AsHookSupport(ag)
1098→		if !ok {
1099→			continue
1100→		}
1101→		wasInstalled := hs.AreHooksInstalled(ctx)
1102→		if err := hs.UninstallHooks(ctx); err != nil {
1103→			errs = append(errs, err)
1104→		} else if wasInstalled {
1105→			fmt.Fprintf(w, "  Removed %s hooks\n", ag.Type())
1106→		}
1107→	}
1108→	return errors.Join(errs...)
1109→}
