func TestCheckpointRemoteConfig_Owner(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name string
		repo string
		want string
	}{
		{"standard", "org/checkpoints", "org"},
		{"nested", "org/sub/repo", "org"},
		{"no slash", "just-name", ""},
