	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			c := &CheckpointRemoteConfig{Provider: "github", Repo: tt.repo}
			assert.Equal(t, tt.want, c.Owner())
		})
	}
}

